<?php
require_once __DIR__ . '/funcoes_carrinho.php';
ota_ensure_order_tables($conn);
$items=ota_cart_items($conn); $data=$_SESSION['ota_entrega']??[]; $erro='';
if(!$items) ota_redirect('carrinho.php'); if(!$data) ota_redirect('finalizar.php');
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['confirmar'])) {
 if(empty($_SESSION['ota_carrinho']) || empty($_SESSION['ota_entrega'])) ota_redirect('carrinho.php');
 $items=ota_cart_items($conn); $total=ota_cart_total($items); $data=$_SESSION['ota_entrega'];
 try {
  $conn->begin_transaction();
  $forma=$data['forma_pagamento']; $stmt=$conn->prepare('SELECT id_pag FROM pagamento WHERE forma_pag=? LIMIT 1'); $stmt->bind_param('s',$forma); $stmt->execute(); $row=$stmt->get_result()->fetch_assoc(); $stmt->close();
  if($row) $idpag=(int)$row['id_pag']; else { $stmt=$conn->prepare('INSERT INTO pagamento (forma_pag) VALUES (?)'); $stmt->bind_param('s',$forma); $stmt->execute(); $idpag=(int)$conn->insert_id; $stmt->close(); }
  $dataPedido=date('Y-m-d'); $horaPedido=date('H:i:s');
  $stmt=$conn->prepare('INSERT INTO pedido (data_pedido, horario_pedido, total_ped, id_pag2, cpf_cli2) VALUES (?, ?, ?, ?, NULL)'); $stmt->bind_param('ssdi',$dataPedido,$horaPedido,$total,$idpag); $stmt->execute(); $idpedido=(int)$conn->insert_id; $stmt->close();
  $stmt=$conn->prepare('INSERT INTO pedido_itens (id_pedido,id_prod,nome_produto,quantidade,preco_unitario,subtotal) VALUES (?,?,?,?,?,?)');
  foreach($items as $id=>$p) { $nome=$p['prod_nome']; $q=(int)$p['quantidade']; $preco=(float)$p['prod_preco']; $sub=(float)$p['subtotal']; $stmt->bind_param('iisidd',$idpedido,$id,$nome,$q,$preco,$sub); $stmt->execute(); } $stmt->close();
  $sql='INSERT INTO pedido_entrega (id_pedido,nome_cliente,email,telefone,cep,logradouro,numero,complemento,bairro,cidade,estado,referencia,observacoes,forma_pagamento) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)';
  $stmt=$conn->prepare($sql); $stmt->bind_param('isssssssssssss',$idpedido,$data['nome'],$data['email'],$data['telefone'],$data['cep'],$data['logradouro'],$data['numero'],$data['complemento'],$data['bairro'],$data['cidade'],$data['estado'],$data['referencia'],$data['observacoes'],$data['forma_pagamento']); $stmt->execute(); $stmt->close();
  $conn->commit(); $_SESSION['ota_ultimo_pedido']=['id'=>$idpedido,'total'=>$total,'data'=>$data,'items'=>$items]; $_SESSION['ota_carrinho']=[]; unset($_SESSION['ota_entrega']); ota_redirect('confirmar.php?sucesso=1');
 } catch(Throwable $e) { $conn->rollback(); $erro='Não foi possível salvar o pedido. Confira se o banco ota_pasteis está importado e tente novamente.'; }
}
$sucesso=isset($_GET['sucesso']) && !empty($_SESSION['ota_ultimo_pedido']); $pedido=$_SESSION['ota_ultimo_pedido']??null; if($sucesso && $pedido) { $items=$pedido['items']; $data=$pedido['data']; $total=$pedido['total']; }
?><!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Confirmar pedido | Pastelaria OTA</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><style>body{background:#f5f5f5;color:#333;font-family:Arial,sans-serif}.container{max-width:1100px}.hero,.panel{border-radius:14px;padding:24px}.hero{background:#333;color:#fff}.hero i{color:#ffc107}.panel{background:#fff;border:1px solid #e7e7e7;box-shadow:0 5px 16px #00000008}.title2{font-weight:800;border-bottom:1px solid #eee;padding-bottom:13px;margin-bottom:18px}.btnota{background:#e21b23;color:#fff;border:0;border-radius:8px;padding:12px 18px;text-decoration:none;font-weight:bold;display:inline-block}.btnota:hover{background:#bd1018;color:#fff}.back{color:#333;text-decoration:none;font-weight:bold}.total{color:#e21b23;font-size:1.4rem;font-weight:800}</style></head><body><main class="container py-4 py-md-5"><a class="back" href="<?=$sucesso?'../../index.php':'finalizar.php'?>"><i class="bi bi-arrow-left"></i> <?=$sucesso?'Voltar ao início':'Voltar aos dados'?></a><div class="hero mt-3 mb-4"><h1><i class="bi bi-clipboard-check"></i> <?=$sucesso?'Pedido realizado!':'Confirmar pedido'?></h1><p class="mb-0"><?=$sucesso?'Recebemos seu pedido. Guarde o número para consulta.':'Confira os produtos, a entrega e o pagamento antes de concluir.'?></p></div><?php if($erro): ?><div class="alert alert-danger"><?=ota_escape($erro)?></div><?php endif; ?><?php if($sucesso && $pedido): ?><section class="panel mb-4"><div class="text-center py-3"><i class="bi bi-check-circle-fill text-success" style="font-size:3rem"></i><h2 class="mt-3">Obrigado por pedir na OTA!</h2><p>Pedido número <strong>#<?= (int)$pedido['id']?></strong></p><p>Total dos produtos: <strong class="total"><?=ota_money($pedido['total'])?></strong></p><p class="text-secondary">Forma de pagamento: <?=ota_escape($data['forma_pagamento'])?>. O pagamento será combinado conforme a opção escolhida.</p><a class="btnota" href="../../cardapio.php">Voltar ao cardápio</a></div></section><?php else: ?><div class="row g-4"><div class="col-lg-8"><section class="panel mb-4"><h2 class="title2">Produtos do pedido</h2><?php foreach($items as $p): ?><div class="d-flex justify-content-between gap-3 py-2 border-bottom"><div><strong><?=ota_escape($p['prod_nome'])?></strong><div class="small text-secondary">Quantidade: <?=$p['quantidade']?> × <?=ota_money($p['prod_preco'])?></div></div><strong><?=ota_money($p['subtotal'])?></strong></div><?php endforeach; ?></section><section class="panel mb-4"><h2 class="title2">Entrega</h2><p><strong>Destinatário:</strong> <?=ota_escape($data['nome'])?></p><p><strong>Telefone:</strong> <?=ota_escape($data['telefone'])?></p><p><strong>Endereço:</strong> <?=ota_escape($data['logradouro'])?>, <?=ota_escape($data['numero'])?><?=!empty($data['complemento'])?', '.ota_escape($data['complemento']):''?>, <?=ota_escape($data['bairro'])?>, <?=ota_escape($data['cidade'])?> <?=ota_escape($data['estado']??'')?></p><p><strong>CEP:</strong> <?=ota_escape($data['cep']??'Não informado')?></p><?php if(!empty($data['observacoes'])): ?><p><strong>Observações:</strong> <?=nl2br(ota_escape($data['observacoes']))?></p><?php endif; ?></section><section class="panel"><h2 class="title2">Pagamento</h2><?=ota_escape($data['forma_pagamento'])?><p class="small text-secondary mt-2 mb-0">Esta opção apenas registra a forma de pagamento; não há cobrança online.</p></section></div><div class="col-lg-4"><section class="panel"><h2 class="title2">Resumo</h2><div class="d-flex justify-content-between mb-3"><span>Produtos</span><strong><?=count($items)?></strong></div><div class="d-flex justify-content-between"><strong>Total dos produtos</strong><span class="total"><?=ota_money(ota_cart_total($items))?></span></div><p class="small text-secondary mt-3">Entrega a combinar.</p><form method="post" onsubmit="return confirm('Confirmar e registrar este pedido?')"><button class="btnota w-100 mt-3" name="confirmar" value="1" type="submit"><i class="bi bi-check-circle"></i> Confirmar pedido</button></form><a class="d-block text-center mt-3" href="finalizar.php">Editar dados</a></section></div></div><?php endif; ?></main></body></html>
